CREATE TABLE "sv_project_profiles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "project_id" uuid NOT NULL REFERENCES "sv_projects"("id"), "brand_name" text NOT NULL, "primary_domain" text NOT NULL, "public_profiles" jsonb DEFAULT '[]' NOT NULL, "competitor_snapshot" jsonb DEFAULT '[]' NOT NULL, "scenario_snapshot" jsonb DEFAULT '[]' NOT NULL, "confirmed_at" timestamptz, "confirmed_by" text, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "sv_project_profiles_project_unique" ON "sv_project_profiles" ("project_id"); CREATE INDEX "sv_project_profiles_org_idx" ON "sv_project_profiles" ("organization_id"); ALTER TABLE "sv_project_profiles" ENABLE ROW LEVEL SECURITY;
